
import globalVariables from "./globalVariables";

const { ccclass, property } = cc._decorator;

@ccclass
export default class CustomPositioningUI extends cc.Component {

    @property(cc.Node)
    canvas: cc.Node = null;

    @property
    isLeftCornered: boolean = true;

    @property
    isRightCornered: boolean = false;

    // @property
    // isTopCornered: boolean = true;

    // @property
    // isBottomCornered: boolean = false;

    start() {
        
        if (this.isLeftCornered) {
            this.positionAtLeftCorner();
        }
        else {
            this.positionAtRightCorner();
        }
    }


    

    positionAtLeftCorner() {
        let _position = this.node.getPosition();
        let _offSet = 20;
        // position = -1280/2 + buttonWidth/2 - viewport.x * (1280/viewportWidth);
        //  console.log("this.canvas.getContentSize().width " + this.canvas.getContentSize().width);
        _position.x = -this.canvas.getContentSize().width / 2 + this.node.width / 2
            - cc.view.getViewportRect().x * this.canvas.getContentSize().width / cc.view.getViewportRect().width + _offSet;
        _position.y = this.canvas.getContentSize().height / 2 - this.node.height / 2
            + cc.view.getViewportRect().y * this.canvas.getContentSize().height / cc.view.getViewportRect().height - _offSet;

        globalVariables.Instance.canvasTopY = _position.y;
        globalVariables.Instance.canvasLeftX =_position.x;
        //console.log("Position is "+_position)
        // console.log("cc.view.getViewportRect() is "+cc.view.getViewportRect())
        this.node.setPosition(_position);
    }

    // positionAtTopCorner() {
    //     let _position = this.node.getPosition();
    //     let _offSet = 20;
    //     // position = -1280/2 + buttonWidth/2 - viewport.x * (1280/viewportWidth);
    //     //  console.log("this.canvas.getContentSize().width " + this.canvas.getContentSize().width);
    //     _position.x = -this.canvas.getContentSize().height / 2 + this.node.height / 2
    //         - cc.view.getViewportRect().y * this.canvas.getContentSize().height / cc.view.getViewportRect().height + _offSet;
    //     _position.y = this.canvas.getContentSize().width / 2 - this.node.width / 2
    //         + cc.view.getViewportRect().x * this.canvas.getContentSize().width / cc.view.getViewportRect().width - _offSet;
    //     // console.log("Position is "+position)
    //     // console.log("cc.view.getViewportRect() is "+cc.view.getViewportRect())
    //     this.node.setPosition(_position);
    // }

    positionAtRightCorner() {
        let _position = this.node.getPosition();
        let _offSet = 20;
        _position.x = this.canvas.getContentSize().width / 2 - this.node.width / 2
            + cc.view.getViewportRect().x * this.canvas.getContentSize().width / cc.view.getViewportRect().width - _offSet;
        _position.y = this.canvas.getContentSize().height / 2 - this.node.height / 2
            + cc.view.getViewportRect().y * this.canvas.getContentSize().height / cc.view.getViewportRect().height - _offSet;
        this.node.setPosition(_position);
    }


    update (dt) {
        
        if(cc.director.getScene().name == "Title"){
            //console.log("cc.Scene.name",)
            if (this.isLeftCornered) {
                this.positionAtLeftCorner();
            }
            else {
                this.positionAtRightCorner();
            }
        }
        
    }
}
